/* pinyin.js — 汉字 → 拼音首字母速查
 *
 * 原理：GB2312 一级汉字（3755 字）在字节序上就是按拼音排列的，
 *       所以只需存一份 3755 字节的首字母串，再用浏览器内置的 gb18030
 *       解码器重建汉字基准串，indexOf 拿到序号即可查表。
 *
 * 覆盖：GB2312 一级汉字 3755 字 + OVERRIDE 里的常见二级字。
 *       查不到的生僻字原样返回，搜索会自动退回原文匹配。
 *
 * 生成：python deploy/gen-pinyin.py（勿手改）
 */
(function(){
  var L="";
  var OV={砼:'T',堃:'K',淼:'M',垚:'Y',犇:'B',骉:'B',喆:'Z',赟:'Y',昇:'S',昱:'Y',玥:'Y',珺:'J',璟:'J',璞:'P',璇:'X',烨:'Y',炜:'W',钰:'Y',锴:'K',焱:'Y',炅:'J',琰:'Y',鑫:'X'};
  var B=null;

  function build(){
    if(B!==null) return;
    B='';
    if(typeof TextDecoder==='undefined') return;
    var d;
    try{ d=new TextDecoder('gb18030'); }catch(e){ return; }
    var b=new Uint8Array(2), c;
    for(var hi=0xB0; hi<=0xD7 && B.length<L.length; hi++){
      for(var lo=0xA1; lo<=0xFE && B.length<L.length; lo++){
        b[0]=hi; b[1]=lo;
        try{ c=d.decode(b); }catch(e){ continue; }
        if(!c || c.length!==1 || c==='\uFFFD') continue;
        B+=c;
      }
    }
  }

  var cache={};
  /* 单个汉字 → 首字母；非汉字或查不到返回空串 */
  function first(ch){
    if(cache[ch]!==undefined) return cache[ch];
    var r=OV[ch]||'';
    if(!r){
      if(B===null) build();
      if(B){
        var i=B.indexOf(ch);
        if(i>=0 && i<L.length) r=L.charAt(i);
        if(r==='#') r='';
      }
    }
    cache[ch]=r;
    return r;
  }

  /* 整串 → 首字母串；ASCII 原样保留并转小写 */
  function initials(str){
    str=String(str||'');
    var out='', i, ch, c;
    for(i=0;i<str.length;i++){
      ch=str.charAt(i);
      if(ch.charCodeAt(0)<128){ out+=ch.toLowerCase(); continue; }
      c=first(ch);
      out += c ? c.toLowerCase() : ch;
    }
    return out;
  }

  window.PY={ first:first, initials:initials, ready:build };
})();
